def compress_string(s: str) -> str:
    if not s:
        return s
    compressed_string = ''
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed_string += s[i - 1] + str(count)
            count = 1
    compressed_string += s[-1] + str(count)
    return compressed_string if len(compressed_string) < len(s) else s
